/// <summary>
/// /// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METCustTransListingContract</c> contract
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METCustActivityStatementUIBuilder), SysOperationDataContractProcessingMode::CreateUIBuilderForRootContractOnly)
]
class METCustActivityStatementContract extends SrsPrintMgmtContract
{
    boolean             usePrintManagement;
    dateDDMMYYYY        fromDate;
    dateDDMMYYYY        toDate;
    AccountNum          csAccountNum;
    SelectableDataArea  csLegalEntity;
    list                salesTaxCode        = new list(Types::String);
    //list                associatedAccount   = new list(Types::String);
    //list                legalEntity         = new list(Types::String);
    str                 footerNote;

}

